import itertools
clauses = [[1,2,3], [-1,-2,3], [-1,2,-3], [1,-2,-3]]
def sat():
    for bits in itertools.product([False,True], repeat=3):
        assign = {i+1:bits[i] for i in range(3)}
        ok=True
        for cl in clauses:
            sat_clause=False
            for lit in cl:
                var=abs(lit)
                val=assign[var]
                if lit>0 and val: sat_clause=True
                if lit<0 and not val: sat_clause=True
            if not sat_clause:
                ok=False; break
        if ok:
            return True, assign
    return False, None
print(sat())
PY"}

